//! Embedded binary assets.

/// Multi-resolution Windows icon generated by `assets/generate_icon.py`.
pub const APP_ICON_ICO: &[u8] = include_bytes!("../assets/app.ico");

/// One image payload from the embedded `.ico` file.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct IconImage {
    pub width: u32,
    pub height: u32,
    pub data: &'static [u8],
}

/// Parse the ICO directory and pick the image whose edge is closest to the
/// requested size (without going over, when possible).
pub fn best_icon_image(preferred_size: u32) -> Option<IconImage> {
    let bytes = APP_ICON_ICO;
    if bytes.len() < 6 {
        return None;
    }
    let count = u16::from_le_bytes([bytes[4], bytes[5]]) as usize;
    let mut candidates = Vec::with_capacity(count);
    for index in 0..count {
        let start = 6 + index * 16;
        let entry = bytes.get(start..start + 16)?;
        let width = if entry[0] == 0 { 256 } else { entry[0] as u32 };
        let height = if entry[1] == 0 { 256 } else { entry[1] as u32 };
        let length = u32::from_le_bytes(entry[8..12].try_into().ok()?) as usize;
        let offset = u32::from_le_bytes(entry[12..16].try_into().ok()?) as usize;
        let data = bytes.get(offset..offset.checked_add(length)?)?;
        candidates.push(IconImage {
            width,
            height,
            data,
        });
    }

    candidates
        .iter()
        .copied()
        .filter(|image| image.width <= preferred_size)
        .max_by_key(|image| image.width)
        .or_else(|| candidates.iter().copied().min_by_key(|image| image.width))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn icon_directory_is_valid() {
        let icon = best_icon_image(64).expect("embedded icon");
        assert!(icon.width >= 32);
        assert_eq!(icon.width, icon.height);
        assert!(!icon.data.is_empty());
    }

    #[test]
    fn picks_requested_size() {
        let icon = best_icon_image(32).expect("embedded icon");
        assert_eq!(icon.width, 32);
        let large = best_icon_image(256).expect("embedded icon");
        assert_eq!(large.width, 256);
    }
}
